type UserPreference = {
  notificationsEnabled: boolean;
};

export const DEFAULT_USER_ID = "user-1";

const userPreferences = new Map<string, UserPreference>([
  [DEFAULT_USER_ID, { notificationsEnabled: false }],
]);

export function getUserNotificationPreference(userId: string): boolean {
  return userPreferences.get(userId)?.notificationsEnabled ?? false;
}

export function toggleUserNotificationPreference(userId: string): boolean {
  const nextValue = !getUserNotificationPreference(userId);
  userPreferences.set(userId, { notificationsEnabled: nextValue });
  return nextValue;
}

