import { toggleNotificationPreference } from '@/app/actions'
import {
  DEFAULT_USER_ID,
  getUserNotificationPreference,
} from '@/app/lib/user-preferences'
import { connection } from 'next/server'

export default async function Home() {
  await connection()
  const notificationsEnabled = getUserNotificationPreference(DEFAULT_USER_ID)

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{notificationsEnabled ? 'On' : 'Off'}</strong>.
      </p>
      <form action={toggleNotificationPreference}>
        <input type="hidden" name="userId" value={DEFAULT_USER_ID} />
        <button type="submit">
          Turn {notificationsEnabled ? 'Off' : 'On'} Notifications
        </button>
      </form>
    </main>
  )
}

